erase(std::remove_if(tasks.begin(),tasks.end(),[&](const Action&t){return!valid(t);}),tasks.end());if(tasks.empty())break;int pri=10;for(auto&t:tasks)pri=std::min(pri,t.type);std::vector<Action>selected,rest;for(auto&t:tasks)(t.type==pri?selected:rest).push_back(t);auto cost=[&](const Action&t){return t.type==ADD?dist2(t.a,t.d):0;};std::stable_sort(selected.begin(),selected.end(),[&](auto&l,auto&r){return cost(l)<cost(r);});std::vector<Action>batch;for(int p=0;p<2;p++){bool stopped=false;for(auto&t:selected)if(t.player==p){if(stopped){rest.push_back(t);continue;}if(!valid(t))continue;batch.push_back(t);if(pri!=MOVE&&pri!=SPAWN)stopped=true;}}std::stable_sort(batch.begin(),batch.end(),[&](auto&l,auto&r){return cost(l)<cost(r);});for(auto&t:batch)if(valid(t,false)&&((pri!=MOVE&&pri!=SPAWN)||valid(t)))apply(t);tasks=std::move(rest);}turn++;if(finish){if(turn>=200)done=true;else{settle();terminal();}}}void load(std::istream&in){*this=State();in>>n;if(n<1||n>NMAX)throw std::runtime_error("Bad node count");for(int i=0;i<n;i++)in>>x[i]>>y[i]>>u[0][i]>>u[1][i];int e;in>>e;for(int i=0;i<e;i++){int a,b;in>>a>>b;adj[a][b]=adj[b][a]=true;}if(!in)throw std::runtime_error("Bad map");triangles();settle();settle();}std::string json()const{std::ostringstream o;o<<"{\"turn\":"<<turn<<",\"score\":["<<score[0]<<','<<score[1]<<"],\"units\":[";for(int q=0;q<n;q++){if(q)o<<',';o<<'['<<u[0][q]<<','<<u[1][q]<<']';}o<<"],\"edges\":[";bool first=true;for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)if(adj[a][b]){if(!first)o<<',';first=false;o<<'['<<a<<','<<b<<']';}o<<"],\"triangles\":[";first=true;for(auto&t:ts){if(!first)o<<',';first=false;o<<'['<<t->v[0]<<','<<t->v[1]<<','<<t->v[2]<<','<<t->owner<<','<<t->cap[0]<<','<<t->cap[1]<<']';}o<<"],\"done\":"<<(done?"true":"false")<<",\"errors\":["<<parse_errors[0]<<','<<parse_errors[1]<<"]}";return o.str();}};}
