namespace rl{constexpr int FEATURES=128;struct Candidate{int kind=2,src=0,dst=0;std::shared_ptr<Triangle>tri;};struct Group{std::vector<std::array<float,FEATURES>>x;int label=0,phase=0;};struct Decoder{const State&s;int p,style,decisions=0;int pending[NMAX]{},available[NMAX]{},ds[NMAX][NMAX]{};int army[2]{},income[2]{},orientation=1;std::vector<std::string>output;Decoder(const State&state,int player,int teacher):s(state),p(player),style(teacher){float ownx=0,otherx=0;for(int q=0;q<s.n;q++){pending[q]=available[q]=s.u[p][q];for(int i=0;i<2;i++)army[i]+=s.u[i][q];ownx+=s.u[p][q]*s.x[q];otherx+=s.u[1-p][q]*s.x[q];auto d=s.distances(q);for(int j=0;j<s.n;j++)ds[q][j]=d[j];}for(auto&t:s.ts)if(t->owner>=0)income[t->owner]++;orientation=ownx/std::max(1,army[p])>otherx/std::max(1,army[1-p])?-1:1;}std::array<float,26>node(int q)const{std::array<float,26>f{};int k=0;auto put=[&](float v){f[k++]=std::clamp(v,-5.f,5.f);};put(s.u[p][q]/10.f);put(s.u[1-p][q]/10.f);put(std::log1p(s.u[p][q])/3);put(std::log1p(s.u[1-p][q])/3);put(pending[q]/10.f);put(available[q]/10.f);put((pending[q]-s.u[1-p][q])/10.f);put(pending[q]>s.u[1-p][q]);put(pending[q]==s.u[1-p][q]);put(pending[q]<s.u[1-p][q]);int deg=0,nu=0,ne=0,nc=0,ec=0;for(int j=0;j<s.n;j++)if(s.adj[q][j]){deg++;nu+=pending[j];ne+=s.u[1-p][j];nc+=pending[j]>s.u[1-p][j];ec+=pending[j]<s.u[1-p][j];}put(deg/8.f);put(nu/20.f);put(ne/20.f);put(nc/8.f);put(ec/8.f);int owned=0,enemy=0,neutral=0,blocked=0,ready[3]{},need=20;for(auto&t:s.ts)if(std::find(t->v.begin(),t->v.end(),q)!=t->v.end()){owned+=t->owner==p;enemy+=t->owner==1-p;neutral+=t->owner==-1&&t->cap[p];blocked+=!t->cap[p];int r=0,cost=0;for(int a:t->v)if(a!=q){r+=pending[a]>s.u[1-p][a];cost+=std::max(0,s.u[1-p][a]+1-pending[a]);}if(t->cap[p]){ready[r]++;need=std::min(need,cost);}}put(owned/6.f);put(enemy/6.f);put(neutral/6.f);put(blocked/6.f);put(ready[2]/6.f);put(ready[1]/6.f);put(ready[0]/6.f);put(need/6.f);int front=50;for(int j=0;j<s.n;j++)if(s.u[1-p][j])front=std::min(front,ds[q][j]);put(front/10.f);put(orientation*(s.x[q]-960)/960.f);put(orientation*(s.y[q]-540)/540.f);return f;}std::array<float,FEATURES>features(const Candidate&c)const{std::array<float,FEATURES>f{};int k=0;auto put=[&](float v){if(k>=FEATURES)throw std::runtime_error("Feature overflow");f[k++]=std::clamp(v,-5.f,5.f);};put(s.turn/200.f);put(s.score[p]/2000.f);put(s.score[1-p]/2000.f);put((s.score[p]-s.score[1-p])/2000.f);put(army[p]/50.f);put(army[1-p]/50.f);put((army[p]-army[1-p])/50.f);put(income[p]/20.f);put(income[1-p]/20.f);put(s.ts.size()/40.f);put(s.n/50.f);put(std::accumulate(pending,pending+s.n,0)/50.f);put(decisions/100.f);put(style==0?1.f:style==2?.5f:0.f);put(style==1?1.f:style==2?.5f:0.f);put(1);for(int j=0;j<7;j++)put(c.kind==j);auto a=node(c.src),b=node(c.dst);for(float v:a)put(v);for(float v:b)put(v);std::array<float,26>mean{};if(c.tri)for(int q:c.tri->v){auto v=node(q);for(int j=0;j<26;j++)mean[j]+=v[j]/3;}for(float v:mean)put(v);put(std::sqrt(s.dist2(c.src,c.dst))/400);put(ds[c.src][c.dst]/10.f);put(orientation*(s.x[c.dst]-s.x[c.src])/400.f);put(orientation*(s.y[c.dst]-s.y[c.src])/400.f);put(c.tri?c.tri->cap[p]:0);put(c.tri?c.tri->cap[1-p]:0);int minunits=20;if(c.tri)for(int q:c.tri->v)minunits=std::min(minunits,available[q]);put(c.tri?minunits/5.f:0);int from[6],to[6];std::fill(from,from+6,50);std::fill(to,to+6,50);float before=0,after=0,reset_before=0,reset_after=0;for(auto&t:s.ts){int ready=0;for(int q:t->v)ready+=pending[q]>s.u[1-p][q];if(t->cap[p]&&t->owner!=p){int idx=(t->owner==1-p?3:0)+std::min(2,ready);for(int q:t->v)if(pending[q]<=s.u[1-p][q]){from[idx]=std::min(from[idx],ds[c.src][q]);to[idx]=std::min(to[idx],ds[c.dst][q]);}}bool pre=true,post=true,empty_pre=true,empty_post=true;for(int q:t->v){int v=pending[q];if(c.kind==1){v-=(q==c.src);v+=(q==c.dst);}if(c.kind==3)v+=(q==c.dst);pre&=pending[q]>s.u[1-p][q];post&=v>s.u[1-p][q];empty_pre&=pending[q]==0;empty_post&=v==0;}if(t->cap[p]&&t->owner!=p){before+=pre;after+=post;}if(!t->cap[p]){reset_be